def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)

    if not filtered_rows:
        return []

    rotated_rows = filtered_rows[-1:] + filtered_rows[:-1] if len(filtered_rows) > 1 else filtered_rows

    eligible_days = []
    for row in rotated_rows:
        day, is_blackout = row
        if not is_blackout and day % 6 != 0:
            eligible_days.append(day)

    distinct_days = []
    for day in eligible_days:
        if day not in distinct_days:
            distinct_days.append(day)

    return sorted(distinct_days)[:4]

